package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.dream.*; import com.wizzadrds.theworldremembers.memory.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import java.util.*; public final class DreamGameTest{@GameTest public void dreamPersistsAndDoesNotMutateWorld(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);c.runAtTickTime(1,()->{var mm=MemoryManager.get(c.getLevel().getServer());mm.rememberEvent(v.getUUID(),new UUID(0,1),MemoryEventType.NPC_DIED,1,MemoryImportance.IMPORTANT);var d=DreamGenerator.generate(v.getUUID(),mm.memoriesOf(v.getUUID()),0,24000).orElseThrow();DreamManager.get(c.getLevel().getServer()).add(d);if(DreamManager.get(c.getLevel().getServer()).dreamsOf(v.getUUID()).size()!=1){c.fail("Dream was not persisted");return;}if(d.type()==DreamType.IMPOSSIBLE&&d.factual()){c.fail("Impossible dream was marked factual");return;}if(!v.isAlive()){c.fail("Dream generation mutated world state");return;}c.succeed();});}}
